part of 'position.dart';

// Incremental Zobrist hashing for MutablePosition (design spec §9): the
// XOR of one key per (side, pip, count) slot plus one per pinned bit.
// Keys are 30-bit, so every value and intermediate is web-safe; the
// table is generated by a fixed 30-bit xorshift, identical on the VM and
// the web.

const int _zMask = 0x3fffffff;

/// Keys per count slot: counts 0..15.
const int _zCounts = _checkers + 1;

/// Index of the first pinned-bit key: then side * 25 + pip (pips 1..24).
const int _zPinBase = 2 * _stride * _zCounts;

/// `[slot * 16 + count]` for the 52 count slots (count 0 keys 0, so an
/// empty slot costs nothing), then the pinned-bit keys.
final Int32List _zobrist = () {
  final t = Int32List(_zPinBase + 2 * 25);
  var x = 0x2545f491;
  for (var i = 0; i < t.length; i++) {
    if (i < _zPinBase && i % _zCounts == 0) continue;
    // xorshift on 30 bits: each step is a bijection of 0..2^30-1.
    x ^= (x << 13) & _zMask;
    x ^= x >> 17;
    x ^= (x << 5) & _zMask;
    t[i] = x;
  }
  return t;
}();

/// The Zobrist hash of a board, computed from scratch.
int _zobristOf(Uint8List counts, int pinnedOne, int pinnedTwo) {
  var h = 0;
  for (var i = 0; i < counts.length; i++) {
    h ^= _zobrist[i * _zCounts + counts[i]];
  }
  for (var pip = 1; pip <= 24; pip++) {
    if ((pinnedOne >> pip) & 1 == 1) h ^= _zobrist[_zPinBase + pip];
    if ((pinnedTwo >> pip) & 1 == 1) h ^= _zobrist[_zPinBase + 25 + pip];
  }
  return h;
}
